def rotate_dict_values(d, n):
    keys = sorted(d.keys())
    if not keys:
        return {}
    m = len(keys)
    shift = n % m
    vals = [d[k] for k in keys]
    rotated = vals[-shift:] + vals[:-shift] if shift else vals[:]
    return {keys[i]: rotated[i] for i in range(m)}

