def ordinal_rank(nums):
    indexed = sorted(range(len(nums)), key=lambda i: (nums[i], i))
    ranks = [0] * len(nums)
    for pos, idx in enumerate(indexed):
        ranks[idx] = pos + 1
    return ranks

